package e2e
import("encoding/json";"fmt";"net/http";"os";"testing";"time")
func TestMediaControlPublicExportE2E(t *testing.T){a,ctrl:=os.Getenv("MEDIA_AUTH_ADDR"),os.Getenv("MEDIA_CONTROL_ADDR");if a==""||ctrl==""{t.Skip("MEDIA_AUTH_ADDR and MEDIA_CONTROL_ADDR are required")};c:=httpClient(t);login(t,c,a,envOr("MEDIA_AUTH_E2E_USER","smoke"),envOr("MEDIA_AUTH_E2E_PASS","smoke123"));s,b:=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/workspaces",map[string]string{"name":fmt.Sprintf("export-%d",time.Now().UnixNano()),"agent_type":"codex"});if s!=http.StatusCreated{t.Fatalf("workspace: %d %s",s,b)};var w struct{ID string};json.Unmarshal(b,&w);s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/public-exports",map[string]string{"workspace_id":w.ID,"resource_type":"prompt","resource_id":"prompt-1","object_path":"exports/prompt-1.json"});if s!=http.StatusCreated{t.Fatalf("export: %d %s",s,b)};var ex struct{ID,Status string};json.Unmarshal(b,&ex);if ex.ID==""||ex.Status!="pending"{t.Fatalf("unexpected export: %+v",ex)};s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/public-exports/"+ex.ID+"/status",map[string]string{"status":"ready"});if s!=http.StatusOK||!jsonContains(b,`"status":"ready"`){t.Fatalf("ready: %d %s",s,b)};s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/public-exports/"+ex.ID+"/status",map[string]string{"status":"revoked"});if s!=http.StatusOK||!jsonContains(b,`"status":"revoked"`){t.Fatalf("revoke: %d %s",s,b)}}
